#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 998244353LL;
const int MAXN = 500000;

int64 mod_pow(int64 a, int64 b) {
    int64 res = 1;
    while (b > 0) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

int64 mod_inv(int64 a) {
    return mod_pow(a, MOD - 2);
}

int64 fact[MAXN + 10];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    fact[0] = 1;
    for (int i = 1; i <= MAXN; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }

    int tt = 1;
    while (tt--) {
        int n, k;
        cin >> n >> k;
        int64 ans = 0;
        for (int i = 1; i <= n - k + 1; ++i) {
            int cnt = n / i;
            if (cnt < k) continue;
            int64 comb = fact[cnt - 1] * mod_inv(fact[k - 1]) % MOD;
            comb = comb * mod_inv(fact[cnt - k]) % MOD;
            ans += comb;
            if (ans >= MOD) ans -= MOD;
        }
        cout << ans << '\n';
    }
    return 0;
}

